#[test]
fn a_retrying_bind_inside_map_with_entries_and_walk_retries_7602() -> Result<()> {
    for &(program, stdout, stderr, code) in ROWS {
        let got = run_jq_full(&["-nc", program], None)?;
        assert_eq!(
            (got.0.as_str(), got.1.as_str(), got.2),
            (stdout, stderr, code),
            "{program:?}"
        );
    }
    Ok(())
}

/// The issue's own programs, over a value read from the input too, and a compile error inside such
/// an `f`, which stays a closure of its block and hides under that block's own error, as in jq.
#[test]
fn the_issues_programs_answer_as_jq_does_7602() -> Result<()> {
    let k = "[1,\"x\"] as [$a] ?// [$b,$a] | $a";
    for (program, input, want) in [
        (format!("[\"x\"] | map(startswith({k}))"), None, "[true]\n"),
        (
            "to_entries | map(has([1,\"key\"] as [$a] ?// [$b,$a] | $a))".to_string(),
            Some("{\"a\":1}"),
            "[true]\n",
        ),
        (
            format!("[\"x\"] | map(try startswith({k}) catch 9)"),
            None,
            "[true]\n",
        ),
        (format!("map(startswith({k}))"), Some("[\"x\"]"), "[true]\n"),
        (
            "with_entries(select(has([1, \"key\"] as [$a] ?// [$b, $a] | $a)))".to_string(),
            Some("{\"a\":1}"),
            "{\"a\":1}\n",
        ),
    ] {
        let args = match input {
            Some(_) => vec!["-c", program.as_str()],
            None => vec!["-nc", program.as_str()],
        };
        let got = run_jq_full(&args, input)?;
        assert_eq!((got.0.as_str(), got.2), (want, 0), "{program}: {}", got.1);
    }
    for (program, missing) in [
        (
            format!("[\"x\"] | map(startswith({k}) | nosuch), nosuch2"),
            "nosuch2/0",
        ),
        (
            format!("[\"x\"] | map(startswith({k}) | nosuch)"),
            "nosuch/0",
        ),
        (
            format!("[\"x\"] | with_entries(startswith({k}) | nosuch), nosuch2"),
            "nosuch2/0",
        ),
        (
            format!("walk(startswith({k}) | nosuch), nosuch2"),
            "nosuch2/0",
        ),
    ] {
        let got = run_jq_full(&["-nc", program.as_str()], None)?;
        assert_eq!(got.2, 3, "{program}");
        assert!(
            got.1.starts_with(&format!(
                "jq: error: {missing} is not defined at <top-level>, line 1:\n"
            )),
            "{program}: {}",
            got.1
        );
        assert!(
            got.1.ends_with("jq: 1 compile error\n"),
            "{program}: {}",
            got.1
        );
    }
    Ok(())
}
